  INSERT INTO rules (
    id, tenant_id, ax_term, num_regle,
    operator, type_ctrl_computed, natural_language,
    terms, terms_count, is_inter_annexe, involved_annexes,
    zone_texte, valid_from, author_user_id, status,
    created_at, updated_at
  )
  SELECT
    uuidv7(), v_tenant_id,
    r->>'ax_term',
    (r->>'num_regle')::INTEGER,
    r->>'operator',
    r->>'type_ctrl_computed',
    r->>'natural_language',
    (r->'terms'),
    (r->>'terms_count')::INTEGER,
    (r->>'is_inter_annexe')::BOOLEAN,
    ARRAY(SELECT jsonb_array_elements_text(r->'involved_annexes')),
    NULLIF(r->>'zone_texte', ''),
    v_valid_from, v_author_id, 'draft',
    NOW(), NOW()
  FROM jsonb_array_elements(v_data) AS r
  ON CONFLICT (tenant_id, ax_term, num_regle, valid_from) DO NOTHING;

